import { useEffect } from 'react'; import { Pressable, SafeAreaView, StyleSheet, Text, View } from 'react-native'; import { useRouter } from 'expo-router'; import { Ionicons } from '@expo/vector-icons'; import { colors, radius, spacing, type } from '@/theme'; import { loadAlarms, recordChallengeCompletion } from '@/services/storage'; import { stopRinging } from '@/services/alarm-ringer'; import { useTranslation } from '@/i18n';
export default function Success(){const { t } = useTranslation(); const router=useRouter(); useEffect(() => { void stopRinging(); loadAlarms().then((alarms) => recordChallengeCompletion(alarms[0]?.challengeType ?? 'math')); }, []); return <SafeAreaView style={styles.safe}><View style={styles.center}><View style={styles.icon}><Ionicons name="checkmark" size={38} color={colors.paper}/></View><Text style={type.largeTitle}>{t('youreUp')}</Text><Text style={styles.copy}>{t('successCopy')}</Text><Text style={styles.streak}>{t('dayStreak')}</Text></View><Pressable style={styles.button} onPress={()=>router.replace('/(tabs)')}><Text style={styles.buttonText}>{t('backToAlarms')}</Text></Pressable></SafeAreaView>}; const styles=StyleSheet.create({safe:{flex:1,backgroundColor:colors.paper,padding:spacing.lg,justifyContent:'space-between'},center:{alignItems:'center',justifyContent:'center',flex:1},icon:{width:76,height:76,borderRadius:38,backgroundColor:colors.success,alignItems:'center',justifyContent:'center',marginBottom:spacing.lg},copy:{...type.body,color:colors.muted,textAlign:'center',maxWidth:280,lineHeight:24,marginTop:spacing.sm},streak:{color:colors.orange,fontSize:16,fontWeight:'800',marginTop:spacing.lg},button:{backgroundColor:colors.ink,borderRadius:radius.md,padding:spacing.md,alignItems:'center',marginBottom:spacing.sm},buttonText:{color:colors.paper,fontWeight:'800',fontSize:16}});
